const first = $input.first().json;
const body = first.body ?? first;
const data = body?.data ?? {};
const key = data.key ?? {};
const remoteJid = key.remoteJid ?? '';
const fromMe = key.fromMe === true;
const isGroup = remoteJid.endsWith('@g.us');
// WhatsApp novo usa LID (@lid): identidade = telefone (senderPn/remoteJidAlt);
// envio = remoteJid original (responder pelo LID e o que entrega de fato).
let numero = remoteJid.replace(/[^0-9]/g, '');
let jidEnvio = numero;
if (remoteJid.endsWith('@lid')) {
  const pn = key.senderPn || key.remoteJidAlt || '';
  if (pn) numero = pn.replace(/[^0-9]/g, '');
  jidEnvio = remoteJid;
}
const msg = data.message ?? {};
let texto = msg.conversation
  || msg.extendedTextMessage?.text
  || msg.imageMessage?.caption
  || msg.videoMessage?.caption
  || msg.buttonsResponseMessage?.selectedDisplayText
  || msg.listResponseMessage?.title
  || '';
texto = String(texto).trim();
const mtype = data.messageType || '';
let tipoMsg = 'texto';
if (mtype === 'audioMessage' || msg.audioMessage) tipoMsg = 'audio';
else if (mtype === 'imageMessage' || msg.imageMessage) tipoMsg = 'imagem';
const messageId = key.id ?? `noid-${Date.now()}`;
const valida = !fromMe && !isGroup && numero.length >= 10 && numero.length <= 15 && (!!texto || tipoMsg !== 'texto');
return [{ json: { valida, numero, jidEnvio, texto, tipoMsg, keyRaw: key, pushName: data.pushName ?? '', messageId, isGroup, fromMe } }];

const msg = $('Extrair mensagem').first().json;
const incr = $input.first().json;
const contagem = Number(Object.values(incr)[0] ?? 1);
return [{ json: { ...msg, contagem, duplicada: contagem > 1 } }];

const r = $input.first().json;
const nome = (($('Contexto').first().json.pushName) || '').split(' ')[0];
let text;
if (r.registrou_agora) {
  text = `🎉 *Bem-vindo(a)${nome ? ', ' + nome : ''}!*

Eu sou o seu *Agente Financeiro* e vou te ajudar a controlar seus gastos direto pelo WhatsApp — simples e prático.

*Como usar:*
• Registrar: _"gastei 25 no almoço"_
• Receita: _"recebi 3000 de salário"_
• Resumo: _"quanto gastei essa semana?"_
• Dicas: _"onde posso economizar?"_
• Relatório: _"me manda um excel"_ ou _"quero um pdf"_
• Limites: _"definir limite de mercado 500"_

Bora começar? Me conta um gasto de hoje! 🚀`;
} else {
  text = `🔒 *Acesso restrito.*

Este é um serviço privado do *Agente Financeiro*.
Para começar, me envie o *código de convite* que você recebeu. 😉`;
}
return [{ json: { text } }];

const r = $input.first().json;
const ctx = $('Contexto').first().json;
const t = (ctx.texto || '').trim();
const admin = !!(r.usuario && r.usuario.admin);
let codigo = null;
if (admin) {
  const temGatilho = /(trocar|mudar|alterar|definir|atualizar|setar|novo|nova)\s+(o\s+|a\s+)?(c[oó]digo|convite)/i.test(t)
    || /^(c[oó]digo|convite)\b/i.test(t);
  if (temGatilho) {
    const ignores = /^(codigo|c[oó]digo|convite|trocar|mudar|alterar|definir|atualizar|setar|novo|nova|para|pro|pra|de|do|da|meu|minha|o|a|os|as|e|é|eh)$/i;
    const tokens = t.split(/\s+/).filter((w) => /^[A-Za-z0-9@#_.-]{4,40}$/.test(w) && !ignores.test(w));
    if (tokens.length) codigo = tokens[tokens.length - 1].toUpperCase();
  }
}
return [{ json: { ...r, admin_comando: !!codigo, codigo } }];

const src = $input.first().json;
const b64 = src.base64 || '';
// valida sem o sufixo "; codecs=opus" e com extensao correta no multipart
let mimetype = String(src.mimetype || 'audio/ogg').split(';')[0].trim() || 'audio/ogg';
const extMap = { 'audio/ogg':'ogg','audio/opus':'opus','audio/wav':'wav','audio/x-wav':'wav','audio/mpeg':'mp3','audio/mp3':'mp3','audio/mp4':'mp4','audio/m4a':'m4a','audio/webm':'webm','audio/flac':'flac' };
const fileName = 'audio.' + (extMap[mimetype] || 'ogg');
if (!b64) return [{ json: { semMidia: true } }];
return [{ json: {}, binary: { data: { data: b64, mimeType: mimetype, fileName } } }];

const ctx = $('Contexto').first().json;
const cur = $input.first().json || {};
const transcricao = (typeof cur.text === 'string') ? cur.text.trim() : '';
const textoFinal = transcricao || ctx.texto || '';
return [{ json: { ...ctx, textoFinal } }];

const m = $input.first().json || {};
const b64 = m.base64 || '';
const mimetype = m.mimetype || 'image/jpeg';
const GM = $env.GEMINI_API_KEY || '';
const OR = $env.OPENROUTER_API_KEY || '';
const prompt = "Você é um extrator de gastos de um agente financeiro. Analise a imagem (nota fiscal, recibo, comprovante ou print de app/banco) e extraia os gastos. Regras: se for UMA compra/nota, registre UMA despesa com o VALOR TOTAL; se for uma lista de transações, registre CADA transação. Ignore transferências entre contas próprias. Se houver parcelamento (ex.: '7/12', '10x de R$ 50', '12x'), informe parcelas. Em parcela: 'valor' = valor da parcela; 'valor_total' = total da compra (parcela x parcelas); 'parcelas' = {\"atual\":7,\"total\":12}. Categorias válidas: Alimentação, Mercado, Transporte, Moradia, Contas fixas, Saúde, Educação, Lazer, Compras, Assinaturas, Viagem, Pets, Outros. Responda SOMENTE JSON: {\"gastos\":[{\"descricao\":\"...\",\"valor\":0.00,\"valor_total\":null,\"parcelas\":{\"atual\":7,\"total\":12},\"categoria\":\"...\",\"tipo\":\"despesa\",\"data\":null}]}. Se não identificar gastos, responda {\"gastos\":[]}.";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let raw = '';
for (let a = 0; a < 3 && !raw; a++) {
  if (a > 0) await sleep(4000);
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3-flash-preview:generateContent?key=' + GM,
      headers: { 'Content-Type': 'application/json' },
      body: { contents: [{ parts: [{ text: prompt }, { inline_data: { mime_type: mimetype, data: b64 } }] }],
              generationConfig: { temperature: 0.1, maxOutputTokens: 1200, thinkingConfig: { thinkingBudget: 0 } } },
      json: true,
      timeout: 120000
    });
    raw = (resp && resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts && resp.candidates[0].content.parts[0].text) || '';
  } catch (e) {}
}
if (!raw && OR) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + OR },
      body: { model: 'google/gemma-4-26b-a4b-it:free',
              messages: [{ role: 'user', content: [{ type: 'text', text: prompt }, { type: 'image_url', image_url: { url: 'data:' + mimetype + ';base64,' + b64 } }] }],
              max_tokens: 600 },
      json: true,
      timeout: 120000
    });
    raw = (resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
    } catch (e) {}
}
if (!raw && b64) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://financas-media:3000/parse-print',
      headers: { 'Content-Type': 'application/json' },
      body: { base64: b64, mimetype },
      json: true,
      timeout: 120000
    });
    if (resp && Array.isArray(resp.gastos) && resp.gastos.length) raw = JSON.stringify({ gastos: resp.gastos });
  } catch (e) {}
}
return [{ json: { raw, temImagem: !!b64 } }];

const r = $input.first().json || {};
let raw = (r && r.raw) || '';
let gastos = [];
try {
  const m = raw.match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(m ? m[0] : raw);
  if (Array.isArray(parsed.gastos)) gastos = parsed.gastos;
} catch (e) { gastos = []; }
const ctx = $('Contexto').first().json;
gastos = (gastos || []).map((g) => {
const parcelas = (g && g.parcelas) || null;
let pAtual = (g && g.parcela_atual) ? Number(g.parcela_atual) : null;
let pTotal = (g && g.parcelas_total) ? Number(g.parcelas_total) : null;
if (parcelas && typeof parcelas === 'object') {
  pAtual = Number(parcelas.atual) || null;
  pTotal = Number(parcelas.total) || null;
}
  const catRec = String((g && g.categoria) || 'Outros').slice(0, 60);
  let valor = Math.round((Number(g && g.valor) || 0) * 100) / 100;
  let valorTotal = (g && g.valor_total) ? Math.round(Number(g.valor_total) * 100) / 100 : null;
  if (valorTotal === null && pTotal) valorTotal = Math.round(valor * pTotal * 100) / 100;
  return {
    descricao: String((g && g.descricao) || 'Gasto').slice(0, 120),
    valor,
    valor_total: valorTotal,
    parcela_atual: pAtual,
    parcelas_total: pTotal,
    categoria: catRec,
    tipo: (g && g.tipo === 'receita') ? 'receita' : 'despesa',
    recorrente: (pTotal === null) && (['Assinaturas', 'Contas fixas'].includes(catRec)),
    data: (g && typeof g.data === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(g.data)) ? g.data : null
  };
}).filter((g) => g.valor > 0);
return [{ json: { numero: ctx.numero, gastos } }];

const r = $input.first().json || {};
const ctx = $('Contexto').first().json || {};
const brl = (v) => 'R$ ' + Number(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
let inseridos = r.inseridos || [];
if (typeof inseridos === 'string') { try { inseridos = JSON.parse(inseridos); } catch (e) { inseridos = []; } }
const nome = (ctx.pushName || '').split(' ')[0];
let text;
if (!Array.isArray(inseridos) || !inseridos.length) {
  text = `📷 ${nome ? nome + ', não' : 'Não'} consegui identificar gastos nessa imagem. Tenta mandar um print mais nítido (com o valor e a descrição legíveis). 😕`;
} else {
  const soma = inseridos.reduce((s, g) => s + Number(g.valor || 0), 0);
  const itens = inseridos.map((g, i) => `${i + 1}. ${g.descricao} — *${brl(g.valor)}* (${g.categoria})`).join('\n');
  text = `📷 *Registrei pelo seu print!*\n\n${itens}\n\n💰 *Total desta imagem:* ${brl(soma)}`;
}
return [{ json: { text } }];

const raw = ($input.first().json.text ?? '').toString();
let parsed = {};
try {
  const m = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : raw);
} catch (e) { parsed = {}; }
const msg = $('Contexto').first().json;
const validIntents = ['registrar','resumo','relatorio','dica','limite','listar','remover','editar','conversa'];
const intent = validIntents.includes(parsed.intent) ? parsed.intent : 'conversa';
let valor = Number(parsed.valor ?? 0);
if (!isFinite(valor) || valor < 0) valor = 0;
valor = Math.round(valor * 100) / 100;
let parcelaAtual = null, parcelasTotal = null;
if (parsed.parcelas && typeof parsed.parcelas === 'object') {
  parcelaAtual = Number(parsed.parcelas.atual) || null;
  parcelasTotal = Number(parsed.parcelas.total) || null;
}
const valorTotal = (parcelasTotal) ? Math.round(valor * parcelasTotal * 100) / 100 : null;
const novoValor = (intent === 'editar' && parsed.novo_valor != null)
  ? (Math.round((Number(parsed.novo_valor) || 0) * 100) / 100) : null;
const catNorm = String(parsed.categoria ?? 'Outros').slice(0, 60) || 'Outros';
const recorrenteAuto = ['Assinaturas', 'Contas fixas', 'Financiamento', 'Moradia'].includes(catNorm);
const recorrente = (parsed.recorrente === true)
  || (recorrenteAuto && parcelasTotal === null && valor > 0);
let multiGastos = null;
if (Array.isArray(parsed.gastos) && parsed.gastos.length > 1) {
  multiGastos = parsed.gastos.map((g) => {
    const pc = (g && g.parcelas) || null;
    let pa = (g && g.parcela_atual) ? Number(g.parcela_atual) : null;
    let pt = (g && g.parcelas_total) ? Number(g.parcelas_total) : null;
    if (pc && typeof pc === 'object') { pa = Number(pc.atual) || null; pt = Number(pc.total) || null; }
    const catM = String((g && g.categoria) || 'Outros').slice(0, 60) || 'Outros';
    let vM = Math.round((Number(g && g.valor) || 0) * 100) / 100;
    if (!isFinite(vM) || vM < 0) vM = 0;
    const vtM = pt ? Math.round(vM * pt * 100) / 100 : null;
    const recAutoM = ['Assinaturas', 'Contas fixas', 'Financiamento', 'Moradia'].includes(catM);
    const recM = (g && g.recorrente === true) || (recAutoM && pt === null && vM > 0);
    return { descricao: String((g && g.descricao) || 'Gasto').slice(0, 200),
      valor: vM, valor_total: vtM, parcela_atual: pa, parcelas_total: pt,
      categoria: catM, tipo: (g && g.tipo === 'receita') ? 'receita' : 'despesa',
      recorrente: recM,
      data: (g && typeof g.data === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(g.data)) ? g.data : null };
  }).filter((x) => x.valor > 0);
}
return [{ json: {
  intent,
  numero: msg.numero,
  textoUsuario: ($('Definir texto').first().json.textoFinal || msg.texto),
  pushName: msg.pushName,
  descricao: String(parsed.descricao ?? '').slice(0, 200) || 'Gasto',
  valor,
  valor_total: valorTotal,
  parcela_atual: parcelaAtual,
  parcelas_total: parcelasTotal,
  tipo: parsed.tipo === 'receita' ? 'receita' : 'despesa',
  categoria: catNorm,
  recorrente,
  multiGastos,
  data: (typeof parsed.data === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(parsed.data)) ? parsed.data : null,
  periodo: ['hoje','semana','mes'].includes(parsed.periodo) ? parsed.periodo : 'mes',
  formato: parsed.formato === 'pdf' ? 'pdf' : 'excel',
  alvo: (parsed.alvo != null ? String(parsed.alvo).slice(0,120) : null),
  novoValor,
  novaDescricao: (parsed.nova_descricao != null ? String(parsed.nova_descricao).slice(0,120) : null),
  novaCategoria: (parsed.nova_categoria != null ? String(parsed.nova_categoria).slice(0,60) : null),
  novaData: (typeof parsed.nova_data === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(parsed.nova_data)) ? parsed.nova_data : null
} }];

const r = $input.first().json || {};
let inseridos = r.inseridos || [];
if (typeof inseridos === 'string') { try { inseridos = JSON.parse(inseridos); } catch (e) { inseridos = []; } }
if (!Array.isArray(inseridos) || !inseridos.length) return [{ json: { text: '🤖 Nada foi registrado.' } }];
const brl = (v) => 'R$ ' + Number(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const linhas = inseridos.map((g) => `${g.descricao} — *${brl(g.valor)}* (${g.categoria})${g.recorrente ? ' 🔁' : ''}`).join('\n');
const soma = inseridos.reduce((s, g) => s + Number(g.valor || 0), 0);
return [{ json: { text: `✅ *Registrei tudo:*\n${linhas}\n\n💰 *Soma lançada:* ${brl(soma)}` } }];

