INSERT INTO orcamentos (numero, categoria, limite_mensal)
SELECT $1, $2, $3 WHERE $3 > 0
ON CONFLICT (numero, categoria) DO UPDATE SET limite_mensal = EXCLUDED.limite_mensal;

SELECT COALESCE(json_agg(json_build_object('categoria', categoria, 'limite', limite_mensal, 'gasto_mes', gasto_mes) ORDER BY categoria), '[]'::json) AS limites
FROM (
  SELECT o.categoria, o.limite_mensal,
    COALESCE((SELECT SUM(g.valor) FROM gastos g WHERE g.numero=$1 AND g.categoria=o.categoria AND g.tipo='despesa' AND date_trunc('month',g.data)=date_trunc('month',CURRENT_DATE)),0) AS gasto_mes
  FROM orcamentos o WHERE o.numero=$1
) t;

