const base = $('Interpretar IA').first().json;
const item = $input.first().json;
const dados = {};
if (base.intent === 'registrar') {
  dados.gasto = item.gasto;
  dados.total_hoje = item.total_hoje;
  dados.total_semana = item.total_semana;
  dados.total_mes = item.total_mes;
  dados.limites = item.limites;
} else if (base.intent === 'resumo') {
  dados.periodo = item.periodo;
  dados.total = item.total;
  dados.por_categoria = item.por_categoria;
} else if (base.intent === 'dica') {
  dados.total_mes = item.total_mes;
  dados.renda_mes = item.renda_mes;
  dados.por_categoria = item.por_categoria;
  dados.limites = item.limites;
} else if (base.intent === 'limite') {
  dados.limites = item.limites;
  dados.categoria = base.categoria;
  dados.valor = base.valor;
} else if (base.intent === 'conversa') {
  dados.total_mes = item.total_mes;
  dados.renda_mes = item.renda_mes;
  dados.por_categoria = item.por_categoria;
  dados.limites = item.limites;
}
return [{ json: {
  intent: base.intent,
  mensagemUsuario: base.textoUsuario,
  nome: base.pushName,
  dados
} }];

const base = $('Interpretar IA').first().json;
const rows = $input.all().map(i => i.json);
const total = rows.reduce((s, r) => s + Number(r.valor || 0), 0);
const mapa = {};
for (const r of rows) mapa[r.categoria] = (mapa[r.categoria] || 0) + Number(r.valor || 0);
const por_categoria = Object.entries(mapa).map(([categoria, t]) => ({ categoria, total: t })).sort((a, b) => b.total - a.total);
return [{ json: {
  numero: base.numero,
  periodo: base.periodo,
  formato: base.formato,
  gerado_em: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
  total,
  por_categoria,
  linhas: rows
} }];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: {
  media: buffer.toString('base64'),
  fileName: 'relatorio-financeiro.xlsx',
  mimetype: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  caption: '📊 Seu relatório financeiro em Excel'
} }];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: {
  media: buffer.toString('base64'),
  fileName: 'relatorio-financeiro.pdf',
  mimetype: 'application/pdf',
  caption: '📄 Seu relatório financeiro em PDF'
} }];

const ctx = $('Contexto').first().json;
const r = $input.first().json || {};
const draft = r.rascunho || '';
let gastos = [];
try { gastos = JSON.parse(draft); } catch (e) { gastos = []; }
const tl = (ctx.texto || '').trim().toLowerCase();
let acao = 'nao', idx = null, valor = null, tipoAjuste = null;
if (/^(salvar|salve|confirmar|confirmo|ok)\s*[!.?]*$/i.test(tl)) acao = 'salvar';
else if (/(cancelar|descartar|esquecer|nada)/.test(tl)) acao = 'cancelar';
else {
  const mDel = tl.match(/(remover|tirar|apagar|deletar)\s*(?:o |a |item )?(\d+)/);
  const mEd = tl.match(/(editar|edita|edite|ajustar|corrigir|mudar)\s*(?:o |a |item )?(\d+)\s*(?:para|pra|de)?\s*([\d.,]+)/);
  if (mDel) { acao = 'ajustar'; tipoAjuste = 'remover'; idx = parseInt(mDel[2], 10); }
  else if (mEd) { acao = 'ajustar'; tipoAjuste = 'editar'; idx = parseInt(mEd[1], 10); valor = parseFloat(mEd[2].replace(/\./g, '').replace(',', '.')); if (!isFinite(valor)) valor = null; }
}
if (acao === 'ajustar' && (idx == null || idx < 1 || idx > gastos.length)) { acao = 'nao'; tipoAjuste = null; idx = null; }
return [{ json: { acao, tipoAjuste, idx, valor, gastos, numero: ctx.numero } }];

const r = $input.first().json || {};
let inseridos = r.inseridos || [];
if (typeof inseridos === 'string') { try { inseridos = JSON.parse(inseridos); } catch (e) { inseridos = []; } }
if (!Array.isArray(inseridos) || !inseridos.length) return [{ json: { text: '🤖 Nada foi salvo (lista vazia).' } }];
const brl = (v) => 'R$ ' + Number(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const linhas = inseridos.map((g, i) => `${i + 1}. ${g.descricao} — *${brl(g.valor)}* (${g.categoria})${g.parcelas_total ? ` (${g.parcela_atual || 1}/${g.parcelas_total})` : ''}`).join('\n');
const soma = inseridos.reduce((s, g) => s + Number(g.valor || 0), 0);
return [{ json: { text: `✅ *Salvei seu print!*\n\n${linhas}\n\n💰 *Total (parcelas deste mês):* ${brl(soma)}` } }];

const r = $input.first().json || {};
const gastos = JSON.parse(JSON.stringify(r.gastos || []));
const idx = r.idx; const tipo = r.tipoAjuste;
if (tipo === 'remover' && gastos[idx - 1]) gastos.splice(idx - 1, 1);
else if (tipo === 'editar' && gastos[idx - 1] && r.valor != null) gastos[idx - 1].valor = r.valor;
return [{ json: { gastos } }];

const r = $input.first().json || {};
const gastos = r.gastos || [];
const ctx = $('Contexto').first().json;
const brl = (v) => 'R$ ' + Number(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const nome = (ctx.pushName || '').split(' ')[0];
if (!Array.isArray(gastos) || !gastos.length) {
  return [{ json: { gastos, text: `📷 ${nome ? nome + ', não' : 'Não'} consegui identificar gastos na imagem. Tenta um print mais nítido. 😕` } }];
}
