WITH lista AS (
  SELECT id, descricao, valor, valor_total, parcela_atual, parcelas_total, categoria, recorrente, to_char(data,'DD/MM/YYYY') AS data
  FROM gastos WHERE numero=$1 AND categoria ILIKE '%'||$2||'%' ORDER BY data DESC, id DESC
), up AS (
  UPDATE usuarios SET ultima_lista = (SELECT COALESCE(json_agg(id), '[]'::json) FROM lista)::jsonb
  WHERE numero=$1 RETURNING numero
)
SELECT COALESCE(json_agg(row_to_json(lista)), '[]'::json) AS itens FROM lista;

